// Main parameters
wall_plate_width = 30;
wall_plate_height = 40;
wall_plate_thickness = 5;

// Hook parameters
hook_thickness = 8;        // Thick for strength
hook_width = 25;           // Wide enough for towels
hook_depth = 35;           // How far hook extends from wall
hook_inner_radius = 12;    // Inner curve radius
hook_tip_length = 15;      // Upward tip to prevent towel slipping

// Screw hole parameters (M3 flat head)
screw_hole_diameter = 3.4;      // Clearance for M3 screw
screw_head_diameter = 6.5;      // M3 flat head diameter
screw_head_depth = 2;           // Countersink depth

// Reinforcement fillet
fillet_radius = 10;

module wall_plate() {
    // Rounded rectangle plate for mounting
    hull() {
        for (x = [-wall_plate_width/2 + 5, wall_plate_width/2 - 5]) {
            for (y = [5, wall_plate_height - 5]) {
                translate([x, y, 0])
                    cylinder(r = 5, h = wall_plate_thickness);
            }
        }
    }
}

module screw_hole() {
    // M3 countersunk hole positioned in upper portion of plate
    translate([0, wall_plate_height - 12, -0.1]) {
        // Through hole
        cylinder(d = screw_hole_diameter, h = wall_plate_thickness + 0.2);
        // Countersink for flat head
        translate([0, 0, wall_plate_thickness - screw_head_depth + 0.1])
            cylinder(d1 = screw_hole_diameter, d2 = screw_head_diameter, h = screw_head_depth + 0.1);
    }
}

module hook_profile() {
    // 2D profile of the hook cross-section
    // Creates a rounded rectangle for strength
    hull() {
        translate([2, 2]) circle(r = 2);
        translate([hook_thickness - 2, 2]) circle(r = 2);
        translate([2, hook_width - 2]) circle(r = 2);
        translate([hook_thickness - 2, hook_width - 2]) circle(r = 2);
    }
}

module hook_arm() {
    // Main hook extending from wall plate

    // Horizontal extension from wall
    translate([wall_plate_thickness, 0, 0])
    rotate([90, 0, 90])
    linear_extrude(height = hook_depth - hook_inner_radius)
        offset(r = 2) offset(r = -2)
        square([hook_width, hook_thickness]);

    // Curved bottom section
    translate([wall_plate_thickness + hook_depth - hook_inner_radius, 0, -hook_inner_radius])
    rotate([90, 0, 0])
    rotate_extrude(angle = 180)
    translate([hook_inner_radius, 0, 0])
        offset(r = 2) offset(r = -2)
        square([hook_thickness, hook_width]);

    // Upward tip section
    translate([wall_plate_thickness + hook_depth - hook_inner_radius - hook_thickness, 0, -hook_inner_radius])
    rotate([90, 0, 90])
    linear_extrude(height = hook_thickness)
        offset(r = 2) offset(r = -2)
        square([hook_width, hook_tip_length]);

    // Rounded tip end
    translate([wall_plate_thickness + hook_depth - hook_inner_radius - hook_thickness/2, hook_width/2, -hook_inner_radius + hook_tip_length])
    scale([hook_thickness/hook_width, 1, 0.5])
        sphere(d = hook_width);
}

module reinforcement() {
    // Triangular reinforcement between wall plate and hook arm
    translate([wall_plate_thickness, 0, 0])
    rotate([90, 0, 0])
    translate([0, 0, -hook_width])
    linear_extrude(height = hook_width)
    polygon([
        [0, 0],
        [fillet_radius * 1.5, 0],
        [0, fillet_radius * 1.5]
    ]);
}

module towel_hook() {
    difference() {
        union() {
            // Wall mounting plate
            rotate([90, 0, 0])
            translate([-wall_plate_width/2, 0, -hook_width])
                wall_plate();

            // Hook arm positioned at bottom of plate
            translate([0, 0, wall_plate_thickness])
                hook_arm();

            // Reinforcement fillet
            translate([0, 0, wall_plate_thickness])
                reinforcement();
        }

        // Screw hole
        rotate([90, 0, 0])
        translate([-wall_plate_width/2, 0, -hook_width])
            screw_hole();
    }
}

// Position hook so wall plate is on XY plane at Z=0
translate([0, -hook_width/2, 0])
rotate([-90, 0, 0])
translate([0, 0, -wall_plate_thickness])
