    linear_extrude(height = t)
    hull() {
        translate([r, r]) circle(r = r);
        translate([w - r, r]) circle(r = r);
        translate([r, h - r]) circle(r = r);
        translate([w - r, h - r]) circle(r = r);
    }
}

module wall_plate() {
    translate([-wall_plate_width/2, 0, 0])
        rounded_rect_plate(wall_plate_width, wall_plate_height, wall_plate_thickness, 5);
}

module screw_hole() {
    // M3 countersunk hole positioned in upper portion of plate
    translate([0, wall_plate_height - 15, -0.1]) {
        // Through hole
        cylinder(d = screw_hole_diameter, h = wall_plate_thickness + 0.2);
        // Countersink for flat head (from back side for flat head screw)
        translate([0, 0, wall_plate_thickness - screw_head_depth + 0.1])
            cylinder(d1 = screw_hole_diameter, d2 = screw_head_diameter, h = screw_head_depth + 0.2);
    }
}

module hook_cross_section() {
    // Rounded rectangle cross section for strength
    hull() {
        translate([2, 2]) circle(r = 2);
        translate([hook_thickness - 2, 2]) circle(r = 2);
        translate([2, hook_width - 2]) circle(r = 2);
        translate([hook_thickness - 2, hook_width - 2]) circle(r = 2);
    }
}

module hook_body() {
    union() {
        // Straight horizontal section
        straight_length = hook_depth - hook_curve_radius - hook_thickness/2;
        translate([wall_plate_thickness, -hook_width/2, hook_thickness/2])
        rotate([-90, -90, 0])
        linear_extrude(height = hook_width)
            hull() {
                translate([2, 0]) circle(r = 2);
                translate([hook_thickness - 2, 0]) circle(r = 2);
                translate([2, straight_length]) circle(r = 2);
                translate([hook_thickness - 2, straight_length]) circle(r = 2);
            }

        // Curved section (180 degrees)
        translate([wall_plate_thickness + straight_length, 0, -hook_curve_radius])
        rotate([90, 0, 0])
        rotate_extrude(angle = 180, convexity = 10)
        translate([hook_curve_radius + hook_thickness/2, 0, 0])
            hull() {
                translate([-hook_thickness/2 + 2, -hook_width/2 + 2]) circle(r = 2);
                translate([hook_thickness/2 - 2, -hook_width/2 + 2]) circle(r = 2);
                translate([-hook_thickness/2 + 2, hook_width/2 - 2]) circle(r = 2);
                translate([hook_thickness/2 - 2, hook_width/2 - 2]) circle(r = 2);
            }

        // Upward return section with taper
        translate([wall_plate_thickness + straight_length - hook_curve_radius - hook_thickness/2, -hook_width/2, -hook_curve_radius])
        rotate([-90, -90, 0])
        linear_extrude(height = hook_width)
