                translate([hook_thickness - 2, 0]) circle(r = 2);
                translate([hook_thickness/2 - 1.5, hook_tip_length]) circle(r = 1.5);
                translate([hook_thickness/2 + 1.5, hook_tip_length]) circle(r = 1.5);
            }
    }
}

module gusset() {
    // Triangular reinforcement for strength
    translate([wall_plate_thickness - 0.1, -hook_width/2, 0])
    rotate([-90, -90, 0])
    linear_extrude(height = hook_width)
    polygon([
        [0, 0],
        [0, gusset_size],
        [gusset_size, 0]
    ]);
}

module towel_hook() {
    difference() {
        union() {
            // Wall plate
            wall_plate();

            // Hook body
            hook_body();

            // Reinforcement gusset
            gusset();
        }

        // Screw hole
        screw_hole();
    }
}

// Render the hook
towel_hook();
