    }
}

module hook_body() {
    // Calculate straight section length
    straight_length = hook_depth - hook_curve_radius - hook_thickness/2;

    union() {
        // Straight horizontal section extending from wall
        translate([wall_plate_thickness, -hook_width/2, 0])
        rotate([0, 90, 0])
        rotate([0, 0, 90])
        linear_extrude(height = straight_length)
